 async function onFile(file){if(!file)return;if(file.type==='text/plain'||file.name.endsWith('.md')){const text=await file.text();$('#storyText').value=text;$('#storyTitle').value=file.name.replace(/\.[^.]+$/,'');updateWordCount();navigate('create');toast('Text loaded. Review it and create your experience.');return}if(file.type==='application/pdf'||file.name.toLowerCase().endsWith('.pdf')){toast('PDF extraction is not available here. Please upload a page image or paste text.');return}if(!file.type.startsWith('image/')){toast('Choose an image or a plain-text file.');return}const image=URL.createObjectURL(file);openOCRImage(image)}
 function openOCRImage(image){openModal(`<button class="modal-close" id="modalClose">×</button><h2>Read a page</h2><p>Text recognition runs in your browser with the open-source Tesseract.js OCR engine. Your photo is not uploaded to a Storyverse server.</p><img src="${image}" style="width:100%;max-height:240px;object-fit:contain;background:#09070f;border-radius:7px"/><div id="ocrStatus" class="license-note">OCR starts when you choose “Extract text”. First use downloads the OCR engine and language data from jsDelivr.</div><div class="modal-actions"><button class="primary-small" id="runOCR">Extract text</button><button class="primary-small" style="background:#201a28;border-color:#554363" id="cancelOCR">Cancel</button></div>`);$('#cancelOCR').onclick=closeModal;$('#runOCR').onclick=()=>runOCR(image)}
 async function runOCR(image){const status=$('#ocrStatus'),button=$('#runOCR');button.disabled=true;button.textContent='Recognizing…';status.textContent='Loading OCR engine and English language data…';try{if(!ocrModule){const src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';await new Promise((resolve,reject)=>{const sc=document.createElement('script');sc.src=src;sc.onload=resolve;sc.onerror=()=>reject(Error('Could not load OCR engine. Check your internet connection.'));document.head.append(sc)});ocrModule=window.Tesseract}const result=await ocrModule.recognize(image,'eng',{logger:m=>{if(m.status)status.textContent=`${m.status}${m.progress?` · ${Math.round(m.progress*100)}%`:''}`}});const text=result.data.text.trim();if(!text)throw Error('No readable text found. Try a sharper, well-lit photo.');status.outerHTML=`<label class="field-label" for="scanTitle">NAME THIS EXPERIENCE</label><input id="scanTitle" class="title-input" maxlength="70" value="Scanned story"/><label class="field-label" for="scanText">RECOGNIZED TEXT <span>Review OCR before listening</span></label><textarea id="scanText" class="story-input scan-text">${escapeHTML(text)}</textarea><div class="license-note">Check the extracted words for OCR mistakes. Only process public-domain, licensed, or otherwise authorized material. Narration uses a voice on this device.</div>`;button.textContent='Create & play';button.disabled=false;button.onclick=()=>createScannedStory(image);$('#cancelOCR').textContent='Edit in studio';$('#cancelOCR').onclick=()=>{const scanned=$('#scanText').value;$('#storyText').value=scanned;$('#storyTitle').value=$('#scanTitle').value;updateWordCount();closeModal();navigate('create')}}catch(e){status.textContent=e.message||'OCR failed. Try another image.';button.disabled=false;button.textContent='Try again'}}
