function narrationChunks(text){const sentences=text.match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[text];const chunks=[];for(const sentence of sentences){let rest=sentence.trim();while(rest.length>360){let cut=rest.lastIndexOf(' ',360);if(cut<180)cut=360;chunks.push(rest.slice(0,cut).trim());rest=rest.slice(cut).trim()}if(rest)chunks.push(rest)}return chunks}
