yle.width='100%');setNarrationStatus('The end');updatePlayerButton();stopAmbience()}catch(error){if(run!==narrationRun)return;playing=false;narrationPaused=false;setNarrationStatus(error.message?.includes('fetch')||!navigator.onLine?'Voice model unavailable · connect to the internet and try again':'Could not create narration · try again');updatePlayerButton();console.error('Kokoro narration failed:',error)}}
