content.text:
.quick-actions
.quick-actions{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:13px 0 32px}
.quick-actions{gap:7px}

.quick-card
.quick-card{min-height:64px;border:1px solid var(--line);background:linear-gradient(130deg,#14101c,#100d17);border-radius:8px;display:flex;align-items:center;text-align:left;padding:10px 12px;gap:10px;transition:.2s}
.quick-card{padding:8px 7px;gap:6px}
.quick-card{min-height:60px;display:grid;grid-template-columns:24px 1fr;column-gap:5px}

.quick-card b
.quick-card b{font-size:10px;display:block;font-weight:600}
.quick-card b{font-size:8px}

.quick-card small
.quick-card small{font-size:8px;color:#888291;display:block;margin-top:4px}
.quick-card small{font-size:7px;line-height:1.4}
.quick-card small{max-width:75px}

.scan-button
.scan-button{display:flex;align-items:center;text-align:left;gap:12px;padding:10px 12px;width:240px;border-radius:7px;border:1px solid #bc96f0;background:linear-gradient(100deg,#a875e8,#8e5bc9);box-shadow:0 5px 25px #9b65de4a;transition:.2s}
.scan-button{width:218px}

.hero-content
.hero-content{position:relative;z-index:1;padding:29px 35px;width:59%;height:100%}
.hero-content{padding:37px 43px}
.hero-content{width:70%}
.hero-content{padding:25px 22px;width:90%}
.hero-content{padding:23px 17px}

.main-content
.main-content{margin-left:242px;padding:0 50px 36px;max-width:1600px}
.main-content{margin-left:242px;padding-right:70px;padding-left:65px}
.main-content{padding:0 27px 30px}
.main-content{margin-left:62px;padding:0 20px 26px}
.main-content{padding-right:13px;padding-left:13px}
.main-content{margin-left:52px}

