async function startNarration(s){const run=++narrationRun;
narrationPaused=false;
playing=true;
$('#playerProgress')&&($('#playerProgress').style.width='0');
$('#cinemaStage')?.classList.remove('is-playing');
const PlayAudio=window.AudioContext||window.webkitAudioContext;
try{ttsAudioCtx ||= new PlayAudio();
await ttsAudioCtx.resume();
updatePlayerButton();
const model=await loadTTS();
if(run!==narrationRun)return;
const chunks=narrationChunks(s.text);
let offset=0;
setNarrationStatus('Preparing your story…');
for(let i=0;
i<chunks.length;
i++){if(run!==narrationRun)return;
const chunk=chunks[i];
if($('#cinemaCaption'))$('#cinemaCaption').textContent=chunk;
setNarrationStatus(narrationPaused?'Paused':'The story is unfolding');
const voiceMap={natural:'af_heart',dramatic:'am_fenrir',gentle:'af_bella',mysterious:'am_onyx'};
const audio=await model.generate(chunk,{voice:voiceMap[s.voice]||'af_heart'});
if(run!==narrationRun)return;
while(narrationPaused&&run===narrationRun)await new Promise(resolve=>narrationWaiters.push(resolve));
if(run!==narrationRun)return;
const samples=audio.audio||audio.data;
if(!samples||!audio.sampling_rate)throw Error('The voice model returned no playable audio.');
const buffer=ttsAudioCtx.createBuffer(1,samples.length,audio.sampling_rate);
buffer.copyToChannel(samples,0);
const source=ttsAudioCtx.createBufferSource();
source.buffer=buffer;
source.connect(ttsAudioCtx.destination);
narrationSource=source;
const started=new Promise(resolve=>source.onended=resolve);
source.start();
playing=true;
updatePlayerButton();
$('#cinemaStage')?.classList.add('is-playing');
setNarrationStatus('The story is unfolding');
if($('#playerProgress'))$('#playerProgress').style.width=`${Math.round(offset/s.text.length*100)}%`;
await started;
narrationSource=null;
offset+=chunk.length;
if($('#playerProgress'))$('#playerProgress').style.width=`${Math.min(100,Math.round(offset/s.text.length*100))}%`}if(run!==narrationRun)return;
playing=false;
narrationPaused=false;
$('#playerProgress')&&($('#playerProgress').style.width='100%');
setNarrationStatus('The end');
updatePlayerButton();
stopAmbience()}
catch(error){if(run!==narrationRun)return;
playing=false;
narrationPaused=false;
setNarrationStatus(error.message?.includes('fetch')||!navigator.onLine?'Voice model unavailable · connect to the internet and try again':'Could not create narration · try again');
updatePlayerButton();
console.error('Kokoro narration failed:',error)}}

